 "content": "def transform(grid):
    """Insert color 2 in the single-cell gaps between adjacent color-0 cells."""
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for c in range(1, len(row) - 1):
            if row[c] == 5 and row[c - 1] == 0 and row[c + 1] == 0:
                out[r][c] = 2
    return out
